function buildModel(name,version,rows,prefix){const processes=rows.map((r,i)=>p(prefix+(i+1),r[0],r[1],/WLT|VSWR|C-CLIP/.test(r[0])?0:1,r[2]||'DÁN & ÉP',/WLT|VSWR|C-CLIP/.test(r[0])));const model={name,version,processes,note:'Dữ liệu khởi tạo từ file IST layout Product.xlsm'};arrange(model);return model}
const seed={models:{s948:buildModel('S948','Ver 0.3',s948Names,'s'),s948b3:buildModel('S948 Block 3','Ver 0.3',b3Names,'b')},versions:[]};
for(const [catalogName,rows] of Object.entries(window.LOB_CATALOG||{})){
  const normalized=catalogName.replaceAll('*','').trim().toLowerCase();
  const exists=Object.values(seed.models).some(m=>m.name.toLowerCase()===normalized||m.name.toLowerCase()===catalogName.toLowerCase());
  if(exists)continue;
  const key='catalog-'+catalogName.toLowerCase().replace(/[^a-z0-9]+/g,'-');
  seed.models[key]=buildModel(catalogName,'Imported',rows.map(r=>[r.name,0,r.category]),key+'-');
  seed.models[key].processes.forEach((station,index)=>{station.skill25=rows[index].skill25==='V';station.skill40=rows[index].skill40==='V'});
  seed.models[key].note='Tên công đoạn lấy từ sheet Thông tin công đoạn từng model; cần nhập T/T.';
}
function arrange(model){model.processes.forEach((s,i)=>{const physical=i*(LINE.tableLength+LINE.gap),lane=Math.floor(physical/LINE.length),meter=physical%LINE.length;s.x=Math.round(meter*LINE.pxPerMeter);s.y=60+lane*94;});}
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toUpperCase().replace(/[^A-Z0-9]+/g,' ').trim();
function applyExcelPositions(target,force=false){const key=Object.keys(window.LOB_POSITIONS||{}).find(k=>norm(k).replaceAll(' ','')===norm(target.name).replaceAll(' ',''));const layout=key&&window.LOB_POSITIONS[key];if(!layout||(!force&&target.excelLayoutApplied))return;for(const item of layout.items){let station=target.processes[item.index];if(item.name){const exact=target.processes.find(s=>norm(s.name)===norm(item.name));const similar=target.processes.find(s=>{const a=norm(s.name),b=norm(item.name);return Math.min(a.length,b.length)>7&&(a.includes(b)||b.includes(a))});station=exact||similar||station}if(!station)continue;station.x=item.x;station.y=item.y;if(!(+station.time)&&item.time)station.time=item.time}target.sourceSheet=layout.sheet;target.excelLayoutApplied=true;}
function enrichSkills(target){const key=Object.keys(window.LOB_CATALOG||{}).find(k=>norm(k).replaceAll(' ','')===norm(target.name).replaceAll(' ',''));const rows=key&&window.LOB_CATALOG[key];if(!rows)return;for(const station of target.processes){const row=rows.find(r=>norm(r.name)===norm(station.name))||rows.find(r=>{const a=norm(r.name),b=norm(station.name);return Math.min(a.length,b.length)>7&&(a.includes(b)||b.includes(a))});if(row){station.skill25=station.skill25??row.skill25==='V';station.skill40=station.skill40??row.skill40==='V'}station.critical=!!station.critical}}
Object.values(seed.models).forEach(m=>applyExcelPositions(m,true));
Object.values(seed.models).forEach(enrichSkills);
let state=structuredClone(seed),currentKey='s948',selectedId=null,history=[],session={role:'viewer',email:''},saveTimer=null;
const $=id=>document.getElementById(id),canEdit=()=>['owner','editor'].includes(session.role),model=()=>state.models[currentKey];
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function getJigs(station){if(!Array.isArray(station.jigs))station.jigs=station.jig||+station.setup?[{name:station.jig||'',setup:+station.setup||0}]:[];return station.jigs}
function metrics(){const a=model().processes,neck=Math.max(0,...a.map(x=>+x.time||0)),sum=a.reduce((n,x)=>n+(+x.time||0),0),mp=a.reduce((n,x)=>n+(+x.mp||0),0);return{neck,sum,mp,uph:neck?3600/neck:0,lob:neck&&a.length?sum/(a.length*neck):0}}
function snapshot(){if(!canEdit())return;history.push(structuredClone(state));if(history.length>30)history.shift()}
function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2200)}
async function request(url,options={}){const response=await fetch(url,{headers:{'content-type':'application/json',...(options.headers||{})},...options});const body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||'Không thể kết nối máy chủ.');return body}
async function boot(){renderRuler();try{const result=await request('/api/layouts');session=result.user||session;for(const row of result.layouts||[]){state.models[row.id]=row.data;applyExcelPositions(state.models[row.id]);enrichSkills(state.models[row.id])}const latest=result.layouts?.find(r=>r.is_latest&&r.model==='S948');if(latest)currentKey=latest.id}catch(error){toast('Đang dùng dữ liệu mẫu: '+error.message)}applyRole();renderAll()}
function applyRole(){document.body.classList.toggle('readonly',!canEdit());$('roleBadge').textContent=session.role==='owner'?'Chủ sở hữu · chỉnh sửa':session.role==='editor'?'Được phép chỉnh sửa':'Chế độ chỉ xem';$('roleBadge').className='role-badge '+(canEdit()?'edit':'view');$('editorsBtn').hidden=session.role!=='owner';$('saveState').innerHTML=canEdit()?'<i></i>Đã đồng bộ':'Chỉ xem công khai';if(!canEdit()&&!session.email&&!document.getElementById('signinBtn'))$('saveState').insertAdjacentHTML('afterend','<a id="signinBtn" class="btn ghost" href="/signin-with-chatgpt?return_to=/" target="_top">Đăng nhập để sửa</a>')}
function renderAll(){renderModels();renderList();renderCanvas();renderMetrics();renderDomainOverview();renderInspector();renderVersions();renderProcessTable()}
function renderModels(){const score=m=>m.version==='Imported'?0:Number((m.version.match(/[\d.]+/)||[0])[0].replaceAll('.',''))+100,groups=new Map();for(const entry of Object.entries(state.models)){const group=norm(entry[1].name).replaceAll(' ','');const existing=groups.get(group);if(!existing||score(entry[1])>score(existing[1]))groups.set(group,entry)}const entries=[...groups.values()].sort((a,b)=>a[1].name.localeCompare(b[1].name));if(!entries.some(([key])=>key===currentKey)){const currentGroup=norm(model().name).replaceAll(' ','');const latest=groups.get(currentGroup);if(latest)currentKey=latest[0]}$('modelSelect').innerHTML=entries.map(([k,m])=>`<option value="${esc(k)}" ${k===currentKey?'selected':''}>${esc(m.name)}${m.version==='Imported'?'':` · ${esc(m.version)}`}</option>`).join('');$('layoutTitle').textContent=`Layout ${model().name}${model().version==='Imported'?'':` · ${model().version}`}`}
function renderMetrics(){const m=metrics(),perSide=Math.floor((LINE.length+LINE.gap)/(LINE.tableLength+LINE.gap)),total=perSide*2,used=model().processes.length,remaining=total-used;$('metricLob').textContent=(m.lob*100).toFixed(1)+'%';$('metricNeck').textContent=m.neck.toFixed(2);$('metricUph').textContent=m.uph.toFixed(0);$('metricCount').textContent=used;$('metricMp').textContent=m.mp+' nhân lực';const note=$('layoutCapacityNote');note.textContent=`Băng chuyền 27 m · bàn 0,8 × 0,5 m · cách 0,5 m · tối đa ${perSide} bàn/cạnh (${total} hai cạnh) · ${model().name}: ${used} vị trí, ${remaining>=0?'còn '+remaining:'vượt '+Math.abs(remaining)}`;note.classList.toggle('over',remaining<0)}
function renderDomainOverview(){const rows=model().processes,countMp=test=>rows.filter(test).reduce((n,s)=>n+(+s.mp||0),0),named=word=>s=>norm(s.name).includes(word),iqc=countMp(named('IQC')),visionLaser=countMp(s=>norm(s.name).includes('VISION LASER')),visionEnd=countMp(s=>norm(s.name).includes('VISION')&&!norm(s.name).includes('LASER')),oqc=countMp(named('OQC')),pqc=countMp(named('PQC')),leader=countMp(named('LEADER')),support=countMp(named('SUPPORT')),qc=iqc+visionLaser+visionEnd+oqc+pqc,production=Math.max(0,metrics().mp-leader-support-qc),dkn=rows.filter(s=>s.skill25||s.skill40).length,total=metrics().mp,type=/BLOCK\s*3/i.test(model().name)?'Block 3':/MAIN/i.test(model().name)?'Main':/SUB/i.test(model().name)?'Sub':'Standard';$('workforceBody').innerHTML=`<tr><td><b>${esc(model().name)}</b></td><td>${type}</td><td>${esc(model().line||'1T')}</td><td>${leader}</td><td>${dkn}</td><td>${support}</td><td><b>${production}</b></td><td>${iqc}</td><td>${visionLaser}</td><td>${visionEnd}</td><td>${oqc}</td><td>${pqc}</td><td><b>${total}</b></td></tr>`;const jigs=rows.flatMap(s=>getJigs(s).map(j=>({...j,process:s.name}))),classify=j=>{const value=norm(j.name+' '+j.process);return value.includes('PRESS')?'press':value.includes('ATTACH')?'attach':'tool'},press=jigs.filter(j=>classify(j)==='press').length,attach=jigs.filter(j=>classify(j)==='attach').length,tool=jigs.filter(j=>classify(j)==='tool').length,setup=jigs.reduce((n,j)=>n+(+j.setup||0),0),stations=rows.filter(s=>getJigs(s).length).length;$('equipmentStats').innerHTML=`<article><span>Jig Press</span><strong>${press}</strong><small>thiết bị</small></article><article><span>Jig Attach</span><strong>${attach}</strong><small>thiết bị</small></article><article><span>Tool khác</span><strong>${tool}</strong><small>công cụ</small></article><article><span>Công đoạn có Jig</span><strong>${stations}/${rows.length}</strong><small>đã khai báo</small></article><article><span>Tổng setup</span><strong>${setup.toFixed(1)}</strong><small>phút</small></article>`}
function renderRuler(){$('meterRuler').innerHTML=Array.from({length:28},(_,i)=>`<span style="left:${i*LINE.pxPerMeter}px">${i}m</span>`).join('')}
function renderList(){const q=$('searchInput').value.toLowerCase();$('processList').innerHTML=model().processes.filter(x=>x.name.toLowerCase().includes(q)).map((x,i)=>`<div class="process-item ${x.id===selectedId?'active':''}" data-id="${esc(x.id)}"><span class="num">${i+1}</span><span class="pname">${esc(x.name)}</span><span class="ptime">${(+x.time).toFixed(2)}s</span></div>`).join('');document.querySelectorAll('.process-item').forEach(el=>el.onclick=()=>select(el.dataset.id))}
function renderCanvas(){const box=$('layoutCanvas'),neck=metrics().neck;box.querySelectorAll('.station').forEach(x=>x.remove());model().processes.forEach((s,i)=>{const el=document.createElement('div');el.className=`station ${s.id===selectedId?'active':''} ${+s.time===neck?'neck':''} ${s.auto?'auto':''} ${s.critical?'critical':''}`;el.dataset.id=s.id;el.style.left=s.x+'px';el.style.top=s.y+'px';el.title=`${i+1}. ${s.name}\nT/T: ${s.time}s · ${s.auto?'AUTO':s.mp+' MP'}\n${s.critical?'Vị trí trọng điểm · ':''}${s.skill40?'Đa kỹ năng 40%':s.skill25?'Đa kỹ năng 25%':''}\nVị trí: ${(s.x/LINE.pxPerMeter).toFixed(1)}m`;el.innerHTML=`<div class="station-no">${i+1}${s.critical?'<i>★</i>':''}</div><div class="station-name">${esc(s.name)}</div><div class="station-meta"><span>${(+s.time).toFixed(2)}s</span><span>${s.auto?'AUTO':`<span class="person-count"><i></i>${s.mp}</span>`}</span></div>${s.skill25||s.skill40?`<div class="skill-badge">ĐKN ${s.skill40?'40':'25'}%</div>`:''}${s.id===selectedId&&canEdit()?'<button class="station-edit" type="button">Sửa</button>':''}`;if(canEdit())el.onpointerdown=startDrag;el.onclick=()=>select(s.id);box.appendChild(el)})}
function select(id){selectedId=id;renderList();renderCanvas();renderInspector();if(innerWidth<=1050)$('inspector').classList.add('open')}
function renderJigs(station){const jigs=getJigs(station);$('jigSummary').textContent=jigs.length?`${jigs.length} Jig · tổng setup ${jigs.reduce((n,j)=>n+(+j.setup||0),0).toFixed(1)} phút`:'Chưa có dữ liệu Jig hoặc setup cho công đoạn này.';$('jigList').innerHTML=jigs.length?jigs.map((j,i)=>`<div class="jig-row" data-index="${i}"><label>Tên Jig<input class="jig-name" value="${esc(j.name||'')}" placeholder="Ví dụ: Press Jig V3"></label><label>Setup (phút)<input class="jig-setup" type="number" min="0" step="0.1" value="${+j.setup||''}" placeholder="0"></label><button class="jig-remove" type="button" title="Xóa Jig">×</button></div>`).join(''):'<div class="jig-empty">Nhấn “+ Thêm Jig” để khai báo Jig đầu tiên.</div>';$('jigList').querySelectorAll('.jig-remove').forEach(button=>button.onclick=()=>{if(!canEdit())return;jigs.splice(+button.closest('.jig-row').dataset.index,1);renderJigs(station)});$('jigList').querySelectorAll('input').forEach(input=>input.disabled=!canEdit())}
function renderInspector(){const s=model().processes.find(x=>x.id===selectedId),form=$('editForm'),empty=$('emptyInspector');if(!s){form.classList.remove('visible');empty.style.display='block';$('stationBadge').textContent='SỬA THỦ CÔNG · TRẠM —';$('stationTitle').textContent='Chọn một trạm';return}empty.style.display='none';form.classList.add('visible');const i=model().processes.indexOf(s);$('stationBadge').textContent=`SỬA THỦ CÔNG · TRẠM ${String(i+1).padStart(2,'0')} · ${(s.x/LINE.pxPerMeter).toFixed(1)}m`;$('stationTitle').textContent=s.name;$('nameInput').value=s.name;$('timeInput').value=s.time;$('mpInput').value=s.mp;$('categoryInput').value=s.category;$('autoInput').checked=s.auto;$('criticalInput').checked=!!s.critical;$('skill25Input').checked=!!s.skill25;$('skill40Input').checked=!!s.skill40;renderJigs(s);form.querySelectorAll('input,textarea,select').forEach(x=>x.disabled=!canEdit())}
function renderProcessTable(){const m=metrics(),rows=model().processes;$('processViewTitle').textContent=`${model().name}${model().version==='Imported'?'':` · ${model().version}`}`;$('processSummary').innerHTML=`<b>LOB ${(m.lob*100).toFixed(1)}%</b><span>Neck ${m.neck.toFixed(2)}s</span><span>UPH ${m.uph.toFixed(0)}</span><span>${rows.length} công đoạn</span>`;$('processTableBody').innerHTML=rows.map((s,i)=>{const ratio=m.neck?(+s.time||0)/m.neck*100:0,isNeck=m.neck>0&&Math.abs((+s.time||0)-m.neck)<.005,status=!s.time?'Chưa có T/T':isNeck?'NECK TIME':s.critical?'TRỌNG ĐIỂM':`Dư ${(m.neck-s.time).toFixed(2)}s`,jigs=getJigs(s),setup=jigs.reduce((n,j)=>n+(+j.setup||0),0);return `<tr data-id="${esc(s.id)}" class="${isNeck?'neck-row':''} ${s.critical?'critical-row':''}"><td>${i+1}</td><td><b>${s.critical?'★ ':''}${esc(s.name)}</b><small>${esc(model().sourceSheet||'Layout')}</small></td><td>${esc(s.category)}</td><td><strong>${(+s.time).toFixed(2)}s</strong></td><td><span class="table-person"><i></i>${s.auto?'AUTO':s.mp}</span></td><td><div class="ratio"><i style="width:${Math.min(100,ratio).toFixed(0)}%"></i></div><span>${ratio.toFixed(0)}%</span></td><td>${s.skill40?'<b>40%</b>':s.skill25?'<b>25%</b>':'<em>—</em>'}</td><td>${jigs.length?jigs.map(j=>esc(j.name||'Jig')).join('<br>'):'<em>Chưa có</em>'}</td><td>${setup?`${setup.toFixed(1)} phút`:'<em>Chưa có</em>'}</td><td><span class="status ${isNeck?'danger':!s.time?'muted':s.critical?'focus':'ok'}">${status}</span></td></tr>`}).join('');$('processTableBody').querySelectorAll('tr').forEach(row=>row.onclick=()=>{select(row.dataset.id);switchView('overview')})}
function renderVersions(){const list=Object.entries(state.models).filter(([,m])=>m.name===model().name).sort((a,b)=>b[1].version.localeCompare(a[1].version));$('versionList').innerHTML=list.map(([,m],i)=>`<div class="version-entry"><b>${esc(m.version)} ${i===0?'<span class="latest">Mới nhất</span>':''}</b><small>${esc(m.note||'Không có ghi chú')}</small></div>`).join('')}
function startDrag(e){if(!canEdit())return;const el=e.currentTarget,s=model().processes.find(x=>x.id===el.dataset.id),canvas=$('layoutCanvas'),r=canvas.getBoundingClientRect(),ox=e.clientX-r.left-s.x,oy=e.clientY-r.top-s.y;snapshot();select(s.id);el.setPointerCapture(e.pointerId);let moved=false;el.onpointermove=ev=>{moved=true;const rawX=Math.max(0,Math.min(LINE.length*LINE.pxPerMeter-72,ev.clientX-r.left-ox));s.x=Math.round(rawX/(LINE.gap*LINE.pxPerMeter))*(LINE.gap*LINE.pxPerMeter);s.y=Math.max(40,Math.min(canvas.clientHeight-55,Math.round((ev.clientY-r.top-oy)/47)*47));el.style.left=s.x+'px';el.style.top=s.y+'px'};el.onpointerup=()=>{el.onpointermove=null;if(moved){scheduleSave();renderInspector();toast('Đã cập nhật vị trí trạm')}}}
async function saveCurrent(isLatest=true){if(!canEdit())return;clearTimeout(saveTimer);$('saveState').innerHTML='<i></i>Đang đồng bộ…';try{const id=currentKey.includes('::')?currentKey:`${model().name}::${model().version}`;await request('/api/layouts',{method:'POST',body:JSON.stringify({id,data:model(),isLatest})});if(id!==currentKey){state.models[id]=model();delete state.models[currentKey];currentKey=id}$('saveState').innerHTML='<i></i>Đã đồng bộ'}catch(error){$('saveState').textContent='Chưa đồng bộ';toast(error.message);throw error}}
