function downloadTemplate(){const rows=[['model','version','process_no','process_name','category','tt_seconds','mp','auto','position_meter','lane','critical_position','multi_skill_25','multi_skill_40','jig_names','jig_setup_minutes'],...model().processes.map((s,i)=>{const jigs=getJigs(s);return[model().name,model().version,i+1,s.name,s.category,s.time,s.mp,s.auto?'YES':'NO',(s.x/LINE.pxPerMeter).toFixed(1),Math.max(1,Math.round((s.y-60)/94)+1),s.critical?'YES':'NO',s.skill25?'YES':'NO',s.skill40?'YES':'NO',jigs.map(j=>j.name).join('; '),jigs.map(j=>j.setup||0).join('; ')]})];const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`LOB_${model().name}_${model().version}.csv`;a.click();URL.revokeObjectURL(a.href)}
function parseCSV(text){const rows=[];let row=[],cell='',quote=false;for(let i=0;i<text.length;i++){const c=text[i],n=text[i+1];if(c==='"'&&quote&&n==='"'){cell+='"';i++}else if(c==='"')quote=!quote;else if(c===','&&!quote){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quote){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(Boolean))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(Boolean))rows.push(row);return rows}
async function importCSV(file){if(!canEdit())return toast('Bạn không có quyền nhập dữ liệu.');const rows=parseCSV(await file.text());if(rows.length<2)throw new Error('File không có dữ liệu.');const headers=rows[0].map(x=>x.trim().replace(/^\ufeff/,'')),idx=n=>headers.indexOf(n),yes=(r,n)=>idx(n)>=0&&(r[idx(n)]||'').trim().toUpperCase()==='YES';for(const required of ['process_name','tt_seconds'])if(idx(required)<0)throw new Error(`Thiếu cột ${required}.`);snapshot();const imported=rows.slice(1).filter(r=>r[idx('process_name')]?.trim()).map((r,i)=>{const s=p('imp'+Date.now()+i,r[idx('process_name')].trim(),Math.max(0,+r[idx('tt_seconds')]||0),Math.max(0,+r[idx('mp')]||0),idx('category')>=0?r[idx('category')]||'DÁN & ÉP':'DÁN & ÉP',yes(r,'auto'));s.x=Math.max(0,(idx('position_meter')>=0?+r[idx('position_meter')]||0:i*1.3)*LINE.pxPerMeter);s.y=60+Math.max(0,(idx('lane')>=0?+r[idx('lane')]||1:1)-1)*94;s.critical=yes(r,'critical_position');s.skill25=yes(r,'multi_skill_25');s.skill40=yes(r,'multi_skill_40');const names=idx('jig_names')>=0?(r[idx('jig_names')]||'').split(';'):[],setups=idx('jig_setup_minutes')>=0?(r[idx('jig_setup_minutes')]||'').split(';'):[];s.jigs=names.map((name,n)=>({name:name.trim(),setup:Math.max(0,+setups[n]||0)})).filter(j=>j.name||j.setup);return s});model().processes=imported;if(idx('model')>=0&&rows[1][idx('model')])model().name=rows[1][idx('model')];if(idx('version')>=0&&rows[1][idx('version')])model().version=rows[1][idx('version')];await saveCurrent();renderAll();toast(`Đã nhập ${imported.length} công đoạn từ Excel`)}
async function loadEditors(){const result=await request('/api/editors');$('editorsList').innerHTML=result.editors.length?result.editors.map(e=>`<div class="editor-row"><span>${esc(e.email)}</span><button type="button" data-email="${esc(e.email)}">Xóa</button></div>`).join(''):'<small>Chưa cấp quyền cho email nào.</small>';document.querySelectorAll('.editor-row button').forEach(b=>b.onclick=async()=>{await request('/api/editors?email='+encodeURIComponent(b.dataset.email),{method:'DELETE'});loadEditors()})}
$('modelSelect').onchange=e=>{currentKey=e.target.value;selectedId=null;renderAll()};$('searchInput').oninput=renderList;
$('editForm').onsubmit=e=>{e.preventDefault();if(!canEdit())return;const s=model().processes.find(x=>x.id===selectedId);if(!s)return;snapshot();s.name=$('nameInput').value.trim()||s.name;s.time=Math.max(0,+$('timeInput').value||0);s.auto=$('autoInput').checked;s.mp=s.auto?0:Math.max(0,+$('mpInput').value||0);s.category=$('categoryInput').value;s.critical=$('criticalInput').checked;s.skill25=$('skill25Input').checked;s.skill40=$('skill40Input').checked;s.jigs=[...$('jigList').querySelectorAll('.jig-row')].map(row=>({name:row.querySelector('.jig-name').value.trim(),setup:Math.max(0,+row.querySelector('.jig-setup').value||0)})).filter(j=>j.name||j.setup);renderAll();scheduleSave();toast('Đã áp dụng thay đổi')};
$('addJigBtn').onclick=()=>{if(!canEdit()||!selectedId)return;const s=model().processes.find(x=>x.id===selectedId);getJigs(s).push({name:'',setup:0});renderJigs(s);$('jigList').querySelector('.jig-row:last-child .jig-name')?.focus()};
$('addBtn').onclick=()=>{if(!canEdit())return;snapshot();const s=p('p'+Date.now(),'Công đoạn mới',10,1);s.x=0;s.y=60;model().processes.push(s);selectedId=s.id;renderAll();select(s.id);scheduleSave()};
$('deleteBtn').onclick=()=>{if(!canEdit()||!selectedId)return;snapshot();model().processes=model().processes.filter(x=>x.id!==selectedId);selectedId=null;renderAll();scheduleSave();toast('Đã xóa công đoạn')};
$('undoBtn').onclick=()=>{if(!canEdit()||!history.length)return toast('Không còn thao tác để hoàn tác');state=history.pop();selectedId=null;renderAll();scheduleSave();toast('Đã hoàn tác')};
$('duplicateBtn').onclick=()=>{if(!canEdit())return;snapshot();const base=model(),key='draft'+Date.now(),copy=structuredClone(base);copy.name=base.name+' Copy';copy.version='Ver 0.1';copy.note='Nhân bản từ '+base.name+' '+base.version;copy.processes.forEach((x,i)=>x.id=key+'-'+i);state.models[key]=copy;currentKey=key;selectedId=null;renderAll();toast('Đã tạo bản sao; hãy lưu version khi hoàn tất')};
$('resetBtn').onclick=()=>{if(!canEdit())return;state=structuredClone(seed);currentKey='s948';selectedId=null;renderAll();toast('Đã khôi phục dữ liệu mẫu cục bộ')};$('printBtn').onclick=()=>window.print();$('closeInspector').onclick=()=>{$('inspector').classList.remove('open');selectedId=null;renderInspector();renderCanvas();renderList()};
$('templateBtn').onclick=downloadTemplate;$('importBtn').onclick=()=>$('fileInput').click();$('fileInput').onchange=e=>{const file=e.target.files[0];if(file)importCSV(file).catch(err=>toast(err.message));e.target.value=''};
$('saveVersionBtn').onclick=()=>{if(!canEdit())return;$('versionName').value=model().version;$('versionNote').value='';$('versionDialog').showModal()};
$('versionForm').addEventListener('submit',async e=>{if(e.submitter?.value==='cancel')return;e.preventDefault();snapshot();const copy=structuredClone(model());copy.version=$('versionName').value.trim()||copy.version;copy.note=$('versionNote').value.trim();const id=`${copy.name}::${copy.version}`;state.models[id]=copy;currentKey=id;$('versionDialog').close();await saveCurrent(true);renderAll();toast('Đã lưu phiên bản mới nhất')});
$('editorsBtn').onclick=async()=>{$('editorsDialog').showModal();await loadEditors()};$('editorsForm').onsubmit=async e=>{e.preventDefault();await request('/api/editors',{method:'POST',body:JSON.stringify({email:$('editorEmail').value})});$('editorEmail').value='';await loadEditors();toast('Đã cấp quyền chỉnh sửa')};
function switchView(view){const overview=view==='overview';$('overviewView').hidden=!overview;$('processView').hidden=overview;document.querySelectorAll('.view-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.view===view));if(overview&&selectedId&&innerWidth<=1050)$('inspector').classList.add('open')}
document.querySelectorAll('.view-tab').forEach(tab=>tab.onclick=()=>switchView(tab.dataset.view));
document.querySelectorAll('.domain-tab').forEach(tab=>tab.onclick=()=>{document.querySelectorAll('.domain-tab').forEach(x=>x.classList.toggle('active',x===tab));document.querySelectorAll('.domain-panel').forEach(panel=>panel.classList.toggle('active',panel.id===tab.dataset.panel))});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){$('undoBtn').click();e.preventDefault()}});
function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;try{c.registerTool({name:'read_lob_summary',title:'Đọc chỉ số LOB',description:'Đọc chỉ số cân bằng của model và version đang mở.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(){return{model:model().name,version:model().version,...metrics(),lineMeters:LINE.length}}})}catch{}}
boot();registerTools();
